function showModal(html){$('#modal').innerHTML=`<div class="modal-overlay" role="dialog" aria-modal="true"><div class="modal-card">${html}</div></div>`;$('#modal .modal-overlay').onclick=e=>{if(e.target.classList.contains('modal-overlay'))closeModal()}}
