function confirmAction(title,body,action,cb){showModal(`<div class="section-head"><h2>${esc(title)}</h2><button class="icon-btn" onclick="closeModal()" aria-label="閉じる">×</button></div><p>${esc(body)}</p><div class="btn-row"><button class="btn" onclick="closeModal()">キャンセル</button><button class="btn danger" id="confirmDo">${esc(action)}</button></div>`);$('#confirmDo').onclick=()=>{closeModal();cb()}}
