function go(path,{replace=false}={}){const h='#/'+path;if(replace)history.replaceState({},'',h);else if(location.hash===h)render();else location.hash=h}
function back(){if(history.length>1)history.back();else go(currentUser()?'home':'landing')}
function requireAuth(target,reason='この操作を保存するにはログインが必要です。'){if(currentUser())return true;sessionStorage.setItem('sm20_after',target);showModal(`<div class="section-head"><h2>ログインが必要です</h2><button class="icon-btn" onclick="closeModal()">×</button></div><p>${esc(reason)}</p><div class="notice">商品やショップの閲覧はログインなしで利用できます。保存・購入・メッセージ等の操作時のみログインが必要です。</div><div class="btn-row" style="margin-top:14px"><button class="btn" onclick="closeModal();go('login')">ログイン</button><button class="btn primary" onclick="closeModal();go('signup')">無料登録</button></div>`);return false}

